// Audit-only quality runner. Preserve historical reports regenerated by Jest.
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const { spawnSync } = require('node:child_process');
const root = path.resolve(__dirname, '../..');
const output = path.join(root, 'docs/atomicidad-fase5d/quality');
fs.mkdirSync(output, { recursive: true });
function files(dir) {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap(entry => {
    if (['node_modules', '.git', 'build', '.gradle'].includes(entry.name)) return [];
    const file = path.join(dir, entry.name);
    return entry.isDirectory() ? files(file) : [file];
  });
}
const protectedFiles = ['src', 'android/app/src', '__tests__', '.agents'].flatMap(dir => files(path.join(root, dir)))
  .concat(['package.json', 'package-lock.json', 'android/app/build.gradle', 'android/build.gradle',
    'scripts/sqliteAndroidRecoveryPatch.js', 'scripts/patchReactNativeSqliteStorage.js',
    'node_modules/react-native-sqlite-storage/platforms/android/src/main/java/org/pgsqlite/SQLitePlugin.java',
    'node_modules/react-native-sqlite-storage/lib/sqlite.core.js'].map(file => path.join(root, file)));
const hash = file => crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');
const before = Object.fromEntries(protectedFiles.map(file => [path.relative(root, file).replaceAll('\\', '/'), hash(file)]));
// Only the existing deterministic test outputs may be restored. Never restore
// arbitrary documents that a collaborator might edit during the quality run.
const generatedReports = [
  'docs/atomicidad-fase3a1/node-equivalence.json',
  'docs/atomicidad-fase4/node-ia-matrix.json',
  'docs/atomicidad-fase4/node-subscriptions-matrix.json',
  'docs/atomicidad-fase4/node-maintenance-comparison.json',
  'docs/performance/shared-commands/node-reader-wait.json',
];
const priorReports = new Map(generatedReports.map(file => path.join(root, file))
  .filter(file => fs.existsSync(file)).map(file => [file, fs.readFileSync(file)]));
const results = [];
const commands = [
  ['jest', process.execPath, ['node_modules/jest/bin/jest.js', '--runInBand', '--json', '--outputFile=docs/atomicidad-fase5d/quality/jest-results.json']],
  ['typescript', process.execPath, ['node_modules/typescript/bin/tsc', '--noEmit']],
  ['eslint', process.execPath, ['node_modules/eslint/bin/eslint.js', '.']],
  ['diff-check', 'git', ['diff', '--check']],
];
for (const [name, command, args] of commands) {
  const started = Date.now();
  const result = spawnSync(command, args, { cwd: root, encoding: 'utf8', maxBuffer: 32 * 1024 * 1024, windowsHide: true });
  fs.writeFileSync(path.join(output, name + '.log'), (result.stdout || '') + (result.stderr || '') + (result.error ? String(result.error) : ''));
  results.push({ name, exitCode: result.status, durationMs: Date.now() - started });
  process.stdout.write(JSON.stringify(results.at(-1)) + '\n');
}
const restoredHistoricalReports = [];
for (const [file, bytes] of priorReports) {
  if (!fs.readFileSync(file).equals(bytes)) {
    restoredHistoricalReports.push(path.relative(root, file).replaceAll('\\', '/'));
    fs.writeFileSync(file, bytes);
  }
}
const after = Object.fromEntries(protectedFiles.map(file => [path.relative(root, file).replaceAll('\\', '/'), hash(file)]));
const changed = Object.keys(before).filter(file => before[file] !== after[file]);
fs.writeFileSync(path.join(output, 'scope-audit.json'), JSON.stringify({ before, after, changed, restoredHistoricalReports }, null, 2));
fs.writeFileSync(path.join(output, 'quality-results.json'), JSON.stringify({ results, protectedFileCount: protectedFiles.length, changed, restoredHistoricalReports }, null, 2));
if (changed.length || results.some(result => result.exitCode !== 0)) process.exitCode = 1;
